/**
 * Render the template from fixture data and save the PDF to Drive.
 * Touches no monday board - safe to run repeatedly.
 */
function runSelfTest() {
  const context = buildContext_(fixtureItem_());
  Logger.log('Placeholders resolved: %s', JSON.stringify(context.fields, null, 1));
  Logger.log('Line items: %s', JSON.stringify(context.lines, null, 1));

  const pdf = renderToPdf_(context, 'SELF TEST - Expense Request');
  const file = outputFolder_().createFile(pdf);

  const checks = [
    ['payee name present', context.fields.payee_name === 'Daniela Spoto'],
    ['date is MM/DD/YYYY like DocuGen',
     context.fields.date_of_request === '08/15/2026'],
    ['mirror Total normalised bare', context.fields.total === '193.19'],
    ['files listed', context.fields.documentation === 'receipt.pdf, calendar.png'],
    ['two line items', context.lines.length === 2],
    ['ampersand intact',
     context.lines[0].budget_category === 'Meals & Entertainment'],
    ['formula amount bare, 2dp', context.lines[0].amount === '181.19'],
    ['numbers column plain, no $', context.lines[0].expense_amt === '181.19'],
    ['whole numbers stay whole', context.lines[1].miles === '20'],
    ['blank dropdown renders empty', context.lines[0].lobbying_fundraising === ''],
    ['dropdown label kept', context.lines[1].lobbying_fundraising === 'Lobbying Expense'],
    ['formula amounts sum when Total is blank',
     formatMoney_(parseAmount_('$181.19') + parseAmount_('$12.00')) === '193.19'],
    ['concatenated mirror Total is not trusted',
     !SINGLE_NUMBER.test('18.50, 142.75')],
    ['pdf produced', pdf.getBytes().length > 1000],
  ];
  checks.forEach(function (check) {
    Logger.log('%s  %s', check[1] ? 'PASS' : 'FAIL', check[0]);
  });
  const failed = checks.filter(function (c) { return !c[1]; });
  Logger.log('%s/%s checks passed - PDF: %s',
             checks.length - failed.length, checks.length, file.getUrl());
  return file.getUrl();
}

// -------------------------------------------------------------- template setup

/** Column widths in points, measured off DocuGen's own PDFs (10in text column). */
var LINE_COLUMNS = [
  ['Name', 141], ['Miles', 33], ['Grants', 153], ['Issue Area', 78],
  ['Project', 155], ['Budget Category', 79], ['Lobbying/Fundraising?', 45],
  ['Amount', 42],
];


/**
 * Create the HA Expense Request template Doc in Drive. Run once.
 *
 * Mirrors the layout DocuGen has been producing: landscape letter, logo left with
 * "Expense Request" to its right, a two-column detail block, the eight-column line-item
 * table, TOTAL REQUEST, Additional Notes, and the check/approval footer.
 */
function setupTemplate() {
  // Re-running should replace the template, not accumulate copies of it.
  const previous = config_('templateId', false);
  if (previous) {
    try {
      DriveApp.getFileById(previous).setTrashed(true);
      Logger.log('Trashed the previous template (%s).', previous);
    } catch (error) {
      Logger.log('Could not trash previous template %s: %s', previous, error);
    }
  }

  const doc = DocumentApp.create('HA Expense Request - docugen template');
  const body = doc.getBody();
  body.clear();
  body.setPageWidth(792).setPageHeight(612);          // landscape letter
  body.setMarginLeft(36).setMarginRight(36).setMarginTop(40).setMarginBottom(36);
  body.setAttributes({});

  // ---- masthead: logo left, title right -------------------------------------
  const masthead = body.appendTable([['', '']]);
  masthead.setBorderWidth(0);
  masthead.setColumnWidth(0, 349);
  masthead.setColumnWidth(1, 371);
  const logoCell = masthead.getCell(0, 0);
  logoCell.setPaddingLeft(0).setPaddingTop(0);
  logoCell.getChild(0).asParagraph().clear();
  const logo = logoCell.getChild(0).asParagraph().appendInlineImage(
    Utilities.newBlob(Utilities.base64Decode(LOGO_B64), 'image/png', 'appleseed-logo.png'));
  // Read the intrinsic ratio BEFORE resizing. Chaining
  //   logo.setWidth(W).setHeight(W * logo.getHeight() / logo.getWidth())
  // looks right but stretches the mark: JS runs the callee (setWidth, which mutates the
  // image) before evaluating the argument, so getWidth() already returns W and the height
  // resolves to its own unchanged value. Like the footer rule, these units are PIXELS at
  // 96dpi, so DocuGen's 3.55in logo is 341px wide, not 256.
  const logoRatio = logo.getHeight() / logo.getWidth();
  logo.setWidth(LOGO_WIDTH_PX);
  logo.setHeight(Math.round(LOGO_WIDTH_PX * logoRatio));

  const titleCell = masthead.getCell(0, 1);
  titleCell.setPaddingRight(0);
  const title = titleCell.getChild(0).asParagraph();
  title.setText('Expense Request');
  title.setAlignment(DocumentApp.HorizontalAlignment.CENTER);
  title.editAsText().setFontSize(26).setBold(false).setFontFamily('Arial');

  // ---- request details ------------------------------------------------------
  const details = body.appendTable([['', ''], ['', ''], ['', '']]);
  details.setBorderWidth(0);
  details.setColumnWidth(0, 331);
  details.setColumnWidth(1, 389);
  const fields = [
    ['Date of Request: ', '{{date_of_request}}', 'Requested By: ', '{{requested_by}}'],
    ['Payee: ', '{{payee_name}}', 'Payee Address: ', '{{payee_address}}'],
    ['Request ID: ', '{{name}}', 'Apt./Ste.: ', '{{apt_ste}}'],
  ];
  fields.forEach(function (row, r) {
    [[0, row[0], row[1]], [1, row[2], row[3]]].forEach(function (pair) {
      const cell = details.getCell(r, pair[0]);
      cell.setPaddingLeft(pair[0] === 0 ? 0 : 4).setPaddingTop(1).setPaddingBottom(1);
      const p = cell.getChild(0).asParagraph();
      p.setText(pair[1] + pair[2]);
      // Matches the DOCX template's paragraph_format.space_after = Pt(6). Cell padding
      // alone (above) is not enough - Docs renders rows tight without this.
      p.setSpacingAfter(6);
      const text = p.editAsText();
      text.setFontSize(9.5).setFontFamily('Arial').setBold(false);
      text.setBold(0, pair[1].length - 1, true);
    });
  });

  body.appendParagraph('').editAsText().setFontSize(4);

  // ---- line items -----------------------------------------------------------
  const headings = LINE_COLUMNS.map(function (c) { return c[0]; });
  const loopRow = LINE_COLUMNS.map(function (c) {
    return c[0] === 'Name' ? '{{line.description}}'
      : '{{line.' + slug_(c[0]) + '}}';
  });
  const items = body.appendTable([
    headings,
    ['{%LINE%}', '', '', '', '', '', '', ''],   // marker row, removed below
    loopRow,
  ]);
  items.setBorderWidth(0.5);
  LINE_COLUMNS.forEach(function (c, i) { items.setColumnWidth(i, c[1]); });

  const headerRow = items.getRow(0);
  headerRow.setMinimumHeight(30);
  for (let i = 0; i < LINE_COLUMNS.length; i++) {
    const cell = headerRow.getCell(i);
    cell.setBackgroundColor('#f2f2f2');
    cell.setVerticalAlignment(DocumentApp.VerticalAlignment.BOTTOM);
    cell.setPaddingTop(2).setPaddingBottom(1);
    cell.editAsText().setFontSize(7.5).setBold(true).setFontFamily('Arial');
  }
  items.removeRow(1);                            // drop the marker row
  const dataRow = items.getRow(1);
  for (let i = 0; i < LINE_COLUMNS.length; i++) {
    const cell = dataRow.getCell(i);
    cell.setPaddingTop(1).setPaddingBottom(1);
    cell.editAsText().setFontSize(8).setBold(false).setFontFamily('Arial');
    if (headings[i] === 'Amount') {
      cell.getChild(0).asParagraph().setAlignment(DocumentApp.HorizontalAlignment.RIGHT);
    }
  }

  // ---- total + notes --------------------------------------------------------
  const total = body.appendParagraph('TOTAL REQUEST: ${{total}}');
  total.editAsText().setFontSize(13).setBold(true).setFontFamily('Arial');
  total.setSpacingBefore(12).setSpacingAfter(6);

  const notes = body.appendParagraph('Additional Notes: {{additional_notes}}');
  const notesText = notes.editAsText();
  notesText.setFontSize(9.5).setBold(false).setFontFamily('Arial');
  notesText.setBold(0, 'Additional Notes:'.length - 1, true);

  // ---- check / approval footer ----------------------------------------------
  const footer = doc.getFooter() || doc.addFooter();

  // The rule: a 1x1 black PNG stretched across the text column. appendHorizontalRule()
  // draws Docs' fixed thin grey line with no styling control - visibly lighter than
  // DocuGen's - and a real paragraph border needs the Docs advanced service, whose
  // restricted scopes this Workspace blocks. A stretched image needs neither and gives
  // exact control over weight.
  const rulePara = footer.appendParagraph('');
  const rule = rulePara.appendInlineImage(
    Utilities.newBlob(Utilities.base64Decode(BLACK_PIXEL_B64), 'image/png', 'rule.png'));
  // InlineImage dimensions are PIXELS (96dpi), not points (72dpi): setWidth(720) came
  // out 540pt on the page, exactly 0.75x. Multiply by 96/72 to land on real points.
  // 960px = 720pt = the 10in text column; 2px = 1.5pt, the same weight as the DOCX
  // template's w:sz=12 border.
  rule.setWidth(960).setHeight(2);
  rulePara.setSpacingBefore(0).setSpacingAfter(8);   // ~0.32in gap down to the text

  // DocuGen leaves 0.32in between the rule and the text, and these exact field gaps
  // (42 / 25 / 107 px) - a 10pt Arial space is ~3.7px, hence 11 / 7 / 29 spaces.
  const footerLine = footer.appendParagraph(
    'Check #:_________' + Array(12).join(' ') +
    'Dated:__________' + Array(8).join(' ') +
    'In the amount of: $__________' + Array(30).join(' ') +
    'Approved by:_____________________________');
  footerLine.editAsText().setFontSize(10).setFontFamily('Arial');

  doc.saveAndClose();
  PropertiesService.getScriptProperties()
                   .setProperty(CONFIG_KEYS.templateId, doc.getId());
  PropertiesService.getScriptProperties()
                   .setProperty(CONFIG_KEYS.templateVersion, TEMPLATE_VERSION);
  Logger.log('Template created and TEMPLATE_DOC_ID saved automatically.');
  Logger.log('Edit it here: %s', doc.getUrl());
  return doc.getUrl();
}
